    "🔥 {name} 赴約了！一起在營火旁坐坐吧": "🔥 {name} came to meet you! Sit by the fire together",
    "📖 圖鑑新收錄：{icon} {name}！+{n} 🌰（{c}／{t}）": "📖 New in your field guide: {icon} {name}! +{n} 🌰 ({c}/{t})",
    "🏆 採集圖鑑全部收集完成！再送你 {n} 顆松果": "🏆 Foraging guide complete! Here are {n} more pinecones",
    "🧺 採到{icon} {name}（採集籃裡有 {n} 個）": "🧺 Picked {icon} {name} ({n} in your basket)",
    "🍄 採集": "🍄 Foraging",
    "🍄 採集圖鑑 {n}／{total}": "🍄 Foraging guide {n}/{total}",
    "採集籃裡 ×{n}": "In basket ×{n}",
    "從營火旁的「🍄 迷霧森林」走進去，走到發光的蘑菇、果實、野花旁邊就會自動採。第一次採到新的種類送松果（★ 越多送越多），全部 {n} 種收集完再送 {b} 顆 🌰": "Walk into 🍄 Misty Woods from the campfire. Step next to glowing mushrooms, berries or wildflowers to pick them automatically. Each new kind gives pinecones (more ★, more pinecones); collect all {n} for {b} more 🌰",
    "🧺 採集籃：總共 {n} 個（不限格子，不會壞）": "🧺 Basket: {n} items (no limit, nothing spoils)",
    "我今天釣到 {size} 公分的{name} 🐟": "I caught a {size} cm {name} today 🐟",
    "帳篷裡擺了 {n} 件家具 ⛺": "{n} pieces of furniture in my tent ⛺",
    "在迷霧森林採了 {n} 樣東西 🍄": "Picked {n} things in Misty Woods 🍄",
    "疊了 {n} 顆石頭許願 🪨": "Stacked {n} wishing stones 🪨",
    "今天穿著{name}": "Wearing {name} today",
    "營火時間進行中！": "Campfire time is on!",
    "今晚 9:30 營火見": "Campfire at 9:30 tonight",
    "流星雨、松果加倍，一起圍著營火烤棉花糖": "Meteor shower, double pinecones — roast marshmallows together",
    "營火時間開始了，快來營火旁找我 🔥": "Campfire time has started — come find me by the fire 🔥",
    "今晚 9:30 一起來營火旁坐坐吧 🔥": "Let's sit by the campfire together at 9:30 tonight 🔥",
    "點連結會直接出現在我旁邊，免安裝打開就能玩：": "Tap the link to appear right next to me — no install needed:",
    "分享出去就送今天的每日造型：{name}　朋友 9:30 營火時間進來，兩個人再拿營火之約限定造型": "Share to get today's outfit: {name}. If your friend joins at 9:30 campfire time, you both get a campfire date outfit too",
    "朋友透過連結來玩，你會拿到每週限定造型；9:30 營火時間進來，兩個人都拿到營火之約限定造型": "When a friend joins via your link you get the weekly outfit; at 9:30 campfire time you both get a campfire date outfit",
    "🍄 迷霧森林": "🍄 Misty Woods",
    "迷霧森林": "Misty Woods",
    "森林裡不能生火，回營火再烤棉花糖吧 🔥": "No fires in the woods — roast marshmallows back at the campfire 🔥",
    "走到發光的蘑菇、果實、野花旁邊，就會自動採進採集籃 🧺": "Walk next to glowing mushrooms, berries or flowers to pick them into your basket 🧺",
    "連上伺服器才能採集喔": "Connect to the server to forage",
    "🌙 晚上（6 點以後）這裡會有螢火蟲和甲蟲": "🌙 Fireflies and beetles show up here at night (after 6 PM)",
    "🌱 這裡剛採過，大約 {h} 小時後長回來": "🌱 Just picked — grows back in about {h} h",
