    "🔥 在料理鍋旁邊，可以開始煮了！": "🔥 You're at the pot — start cooking!",
    "到中央營火旁的「🍲 營火料理」鍋子才能煮。蔬菜在帳篷前的小菜園種。": "Cook at the 🍲 pot by the central campfire. Grow veggies in the garden in front of your tent.",
