    "🥕 我的小菜園": "🥕 My garden",
    "🥕 {name} 的小菜園": "🥕 {name}'s garden",
    "種子免費，種下去等幾小時就能收成，放著不收也不會枯掉。朋友路過可以幫忙澆水，少等 30 分鐘、收成多一個。收成的蔬菜可以拿去營火旁煮料理，或當手作家具的材料。": "Seeds are free. Harvest after a few hours — crops never wither. Friends can water to make them 30 min faster and +1 harvest. Cook veggies at the campfire or use them for crafting.",
    "幫朋友的菜澆水，可以少等 30 分鐘、收成多一個 💧": "Water a friend's crops — 30 min sooner and +1 harvest 💧",
