    "🔥 名字前面的小營火徽章，大家都看得到": "🔥 A little campfire badge before your name that everyone can see",
    "⛺ 月票限定帳篷花色「營火之夜」（買過就一直留著）": "⛺ Pass-exclusive tent pattern \"Campfire Night\" (yours to keep)",
    "購買前要先建立帳號（👤 存檔），換手機登入月票才不會不見": "Create an account first (👤 Save) so your pass follows you to other devices",
    "⚠️ 目前是綠界測試模式，不會真的扣款": "⚠️ ECPay test mode — no real charge",
    "🔥 再買一次（往後延 {n} 天）": "🔥 Buy again (+{n} days)",
    "🔥 購買營火月票 NT$ {p}": "🔥 Buy Campfire Pass NT$ {p}",
    "付款由綠界處理（信用卡、ATM、超商代碼），付款完成後自動開通，不用等人工。月票只會加快松果累積，遊戲裡所有東西不買也都拿得到。": "Payment is handled by ECPay (card, ATM, convenience store) and activates automatically. The pass only speeds up pinecones — everything in the game can be earned without it.",
    "購買前要先建立帳號（👤 存檔）": "Create an account first (👤 Save)",
