    "🐉 {m} 分鐘後 9:30 營火時間！魚王會在湖畔和營火河畔出現，還有流星雨、松果加倍": "🐉 Campfire Time at 9:30 in {m} min! The Fish King appears at the lake and the campfire riverside, plus meteor showers and double pinecones",
