    "造型可以同時戴帽子、背背包、圍圍巾，其他人都看得到 ✨": "帽子・リュック・マフラーを同時に着られて、みんなにも見えるよ ✨",
    "單人模式：連上伺服器才能領造型": "ひとりモード：サーバーにつながるとコーデがもらえる",
    "🌟 朋友透過你的連結來玩了！拿到每週限定造型：{name}": "🌟 友だちがリンクから来てくれた！週替わり限定コーデ「{name}」",
