    "🔥 {name} 赴約了！一起在營火旁坐坐吧": "🔥 {name}さんが約束どおり来たよ！一緒にたき火にあたろう",
    "📖 圖鑑新收錄：{icon} {name}！+{n} 🌰（{c}／{t}）": "📖 図鑑に新登録：{icon} {name}！+{n} 🌰（{c}／{t}）",
    "🏆 採集圖鑑全部收集完成！再送你 {n} 顆松果": "🏆 採集図鑑コンプリート！松ぼっくりを{n}個プレゼント",
