    "採集籃裡 ×{n}": "かごに ×{n}",
    "從營火旁的「🍄 迷霧森林」走進去，走到發光的蘑菇、果實、野花旁邊就會自動採。第一次採到新的種類送松果（★ 越多送越多），全部 {n} 種收集完再送 {b} 顆 🌰": "たき火のそばの「🍄 霧の森」へ。光っているキノコ・木の実・野の花に近づくと自動で採れるよ。新しい種類は初回に松ぼっくり（★が多いほどたくさん）、全{n}種そろうとさらに{b}個 🌰",
    "🧺 採集籃：總共 {n} 個（不限格子，不會壞）": "🧺 採集かご：全部で{n}個（枠の上限なし、腐らない）",
    "我今天釣到 {size} 公分的{name} 🐟": "今日は{size}cmの{name}を釣ったよ 🐟",
