    "營火時間開始了，快來營火旁找我 🔥": "たき火タイムが始まったよ、たき火のそばに来てね 🔥",
    "今晚 9:30 一起來營火旁坐坐吧 🔥": "今夜9:30、一緒にたき火にあたろう 🔥",
