    "分享出去就送今天的每日造型：{name}　朋友 9:30 營火時間進來，兩個人再拿營火之約限定造型": "シェアすると今日のコーデ「{name}」。友だちが9:30のたき火タイムに来たら、ふたりとも約束限定コーデも",
    "朋友透過連結來玩，你會拿到每週限定造型；9:30 營火時間進來，兩個人都拿到營火之約限定造型": "友だちがリンクから来ると週替わり限定コーデ。9:30のたき火タイムならふたりとも約束限定コーデ",
