    "只在每晚 9:30，在營火河畔若隱若現": "毎晩9:30だけ、たき火の川辺に見え隠れする",
    "🌙 每晚 7 點～11 點，每半小時一場小活動（9:30 營火時間有魚王）": "🌙 毎晩7時〜11時、30分ごとにミニイベント（9:30のたき火タイムは魚の王が出るよ）",
    "想動就去釣魚、疊石頭；想靜就在火邊坐著。每晚 7 點～11 點，每半小時一場小活動 🎣": "動きたいなら釣りや石積み、静かにしたいならたき火のそばで。毎晩7時〜11時は30分ごとにミニイベント 🎣",
    "🍄 迷霧森林：地上有發光圈圈的蘑菇、果實、野花，走過去按 E 採摘；空中飛的蟲蟲要用捕蟲網（{p} 🌰）按 E 捕。🐚 湖畔碼頭的岸邊可以撿石頭和貝殼。✨ 晚上 8～10 點營火附近偶爾會有寶藏。第一次找到新的種類送松果，全部收集完再送 {b} 顆 🌰": "🍄 霧の森：光る輪のあるキノコ・木の実・花に近づいてEで採集、飛んでいる虫は虫取り網（{p} 🌰）でEで捕まえる。🐚 湖の岸辺では石や貝がら。✨ 夜8〜10時はたき火の近くにときどき宝物。新しい種類は松ぼっくりがもらえ、全部そろうとさらに{b}個 🌰",
    "🦋 捕蟲網：已經有了": "🦋 虫取り網：持っている",
    "🦋 捕蟲網：還沒有": "🦋 虫取り網：まだない",
    "買一支 🌰 {p}": "買う 🌰 {p}",
    "🥕 菜園收成": "🥕 菜園の収穫",
    "🦋 買了一支捕蟲網！看到空中飛的蟲蟲，走近按 E 捕捉": "🦋 虫取り網を買ったよ！飛んでる虫に近づいてEで捕まえよう",
    "松果不夠，還差 {n} 顆 🌰": "松ぼっくりが足りないよ、あと{n}個 🌰",
    "🦋 捕蟲網": "🦋 虫取り網",
    "空中飛的蟲蟲要用捕蟲網才捕得到。買一支之後一直都能用：白天有瓢蟲、金龜子、螳螂⋯，晚上有螢火蟲、獨角仙、月光蛾⋯": "飛んでいる虫は虫取り網がないと捕まえられないよ。一度買えばずっと使える：昼はテントウムシ・コガネムシ・カマキリ、夜はホタル・カブトムシ・オオミズアオ⋯",
    "🦋 買一支捕蟲網 🌰 {p}": "🦋 虫取り網を買う 🌰 {p}",
