    "湖裡釣魚、湖邊、帳篷營地的路邊、中央營火區，偶爾會出現垃圾，走過去按 E 撿起來。撿到的垃圾拿去營火旁的「♻️ 回收桶」丟，每件換 1 顆松果（每天最多 {cap} 顆）。全部收集完送「淨灘小隊領巾」♻️": "釣りの最中、湖のほとり、キャンプ場の道ばた、たき火のまわりにときどきゴミが出るよ。近づいてEで拾おう。たき火のそばの「♻️ リサイクル箱」に入れると1個につき松ぼっくり1個（1日最大{cap}個）。全部集めると「おそうじ隊のバンダナ」♻️",
