    "新家具：配色、隔間牆、魚缸、展示櫃": "新しい家具：配色、仕切り壁、水槽、飾り棚",
    "買家具可以選顏色；用隔間牆分房間；魚缸放自己釣的魚（魚王要巨型水族箱）；沙發、床按 E 可以坐下、躺下": "家具の色が選べ、壁で部屋を分けられ、水槽に釣った魚を飾れます（魚の王は巨大水族館）。ソファやベッドでEを押すと座ったり横になったり",
