    "「👒 造型 → 🐾 外型」可以買特殊毛色（橘貓、三花⋯）、換尾巴和耳朵形狀": "「👒 コーデ → 🐾 見た目」で特別な毛色（茶トラ、三毛…）やしっぽ・耳の形を買えます",
