    "小舖「🚙 門口擺設」：露營車、越野車、吊床⋯擺在帳篷營地的家門口": "お店の「🚙 玄関の飾り」：キャンピングカー、オフロード車、ハンモック…をテント場の家の前に",
    "📖 上面多了「圖鑑」：釣到的魚、採到的東西都會收在這裡": "📖 上に「図鑑」が出ました：釣った魚や集めたものがここに入ります",
    "👒 「造型」和「🔥 約朋友」打開了：朋友點你的連結進來玩 1 分鐘，就送你今天的造型": "👒 「コーデ」と「🔥 友達を誘う」が開きました：友だちがあなたのリンクから来て1分遊ぶと、今日のコーデがもらえます",
    "💡 歡迎回來！多了「今日小靈感」，每天都有新的小任務": "💡 おかえり！「今日のひらめき」が増えました。毎日新しい小さなタスクがあります",
    "🎉 營地全部打開了：到「🏪 營地小舖」買帳篷，也可以用「🧭 去哪裡」到迷霧森林採集": "🎉 キャンプ場が全部開きました：「🏪 キャンプの売店」でテントを買ったり、「🧭 移動」で霧の森へ採集に行けます",
    "🌙 明天見！": "🌙 また明日！",
    "營地每天都有新東西，明天記得回來看看：": "キャンプ場には毎日新しいことがあります。明日も来てね：",
