    "🌅 早上 9:30、晚上 9:30 營火時間：魚王、流星雨、松果加倍": "🌅 朝9:30・夜9:30は焚き火タイム：魚の王、流れ星、松ぼっくり2倍",
    "👒 每天都有新的每日造型，朋友點你的連結進來玩 1 分鐘就拿到": "👒 毎日新しいコーデ。友だちがあなたのリンクから来て1分遊ぶともらえます",
    "🌙 晚上 7～11 點每半小時一場小活動": "🌙 夜7時〜11時は30分ごとにミニイベント",
