    "⚠️ 還沒建帳號：松果、帳篷只存在這台裝置，清掉瀏覽器資料或換手機就找不回來": "⚠️ まだアカウントがありません：松ぼっくりやテントはこの端末だけに保存。ブラウザのデータを消したりスマホを変えると戻りません",
