    "種子用松果買（越慢長的越貴），種下去等幾小時就能收成，放著不收也不會枯掉。朋友路過可以幫忙澆水，少等 30 分鐘、收成多一個。收成的蔬菜可以拿去營火旁煮料理，或當手作家具的材料。": "씨앗은 솔방울로 사요 (늦게 자랄수록 비싸요). 몇 시간 뒤 수확, 그냥 둬도 시들지 않아요. 친구가 물을 주면 30분 빨라지고 수확 +1. 채소는 모닥불 요리나 가구 재료로.",
    "🌱 種下{icon} {name}了！大約 {h} 小時後收成": "🌱 {icon} {name} 심었어요! 약 {h}시간 뒤 수확",
    "松果不夠喔": "솔방울이 부족해요",
    "沒種成，再試一次吧": "심지 못했어요, 다시 해 봐요",
    "🔥 約朋友・分享送禮": "🔥 친구 초대 · 선물",
    "朋友要「點你的連結」或「掃邀請圖上的 QR Code」進來才算數": "친구가 내 링크를 누르거나 초대 이미지의 QR 코드를 스캔해서 들어와야 인정돼요",
    "📋 複製連結": "📋 링크 복사",
    "📤 分享連結": "📤 링크 공유",
    "🖼️ 邀請圖（有 QR Code）": "🖼️ 초대 이미지 (QR)",
    "👒 今天的每日造型・朋友點你的連結進來玩 1 分鐘，或完成下面的「今日挑戰」": "👒 오늘의 데일리 코디 · 친구가 링크로 1분 놀거나, 아래 「오늘의 도전」 완료",
    "🌟 這週限定造型・朋友第一次透過你的連結來玩，待滿 {m} 分鐘": "🌟 주간 한정 코디 · 친구가 처음 내 링크로 와서 {m}분 머물면",
    "🔥 營火之約限定・晚上 9:30～10:00 朋友透過你的連結進來，兩個人都拿到": "🔥 모닥불 약속 한정 · 밤 9:30~10:00에 친구가 내 링크로 오면 둘 다 획득",
    "{kind}・第一次分享": "{kind} · 첫 공유",
    "{kind}・{n} 位朋友透過你的連結來玩": "{kind} · 친구 {n}명이 내 링크로 접속",
    "已經有 {n} 位朋友透過你的連結來玩。每位朋友第一次來、待滿 {m} 分鐘，你就多 {g} 顆松果。只傳圖片的話，請朋友掃圖上的 QR Code 才算喔": "지금까지 친구 {n}명이 내 링크로 왔어요. 처음 와서 {m}분 머물면 솔방울 {g}개. 이미지만 보낼 땐 QR 코드를 스캔해 달라고 하세요",
    "複製不了，請長按上面的連結自己複製": "복사가 안 돼요, 위 링크를 길게 눌러 복사하세요",
    "📋 已複製邀請連結，貼到 LINE、Threads、IG 給朋友吧": "📋 초대 링크 복사 완료, LINE·Threads·IG에 붙여넣어 친구에게 보내요",
    "有些 App（像 IG、LINE）分享圖片時會把連結拿掉，朋友掃圖上的 QR Code 一樣算是透過你的連結進來 📱": "IG·LINE 같은 앱은 이미지 공유 시 링크가 빠져요. 이미지의 QR 코드를 스캔해도 인정돼요 📱",
    "朋友點連結進來玩 1 分鐘，就送你今天的每日造型：{name}": "친구가 링크로 들어와 1분 놀면 오늘의 코디 {name}를 받아요",
