    "📋 文案和連結複製好了，貼到 LINE、Threads、IG 都可以": "📋 문구와 링크 복사 완료, LINE·Threads·IG에 붙여넣기",
    "✅ 圖片分享出去了！文案和連結也幫你複製好了，如果朋友那邊沒看到連結，在聊天框長按「貼上」就好": "✅ 이미지 공유 완료! 문구와 링크도 복사했어요. 친구에게 링크가 안 갔다면 대화창에 길게 눌러 붙여넣기",
    "✅ 分享出去了！圖片可以按「存圖」另外傳": "✅ 공유 완료! 이미지는 저장해서 따로 보낼 수 있어요",
    "按「📤 分享」會順便複製下面的文案和連結：如果 App 只送出圖片，在聊天框貼上就好；朋友掃圖上的 QR Code 也算 📱": "📤 공유를 누르면 아래 문구와 링크도 복사돼요. 앱이 이미지만 보냈다면 대화창에 붙여넣으면 돼요. QR 코드 스캔도 인정 📱",
