    "營火區": "모닥불 주변",
    "湖裡釣魚、湖邊、帳篷營地的路邊、中央營火區，偶爾會出現垃圾，走過去按 E 撿起來。撿到的垃圾拿去營火旁的「♻️ 回收桶」丟，每件換 1 顆松果（每天最多 {cap} 顆）。全部收集完送「淨灘小隊領巾」♻️": "낚시 중, 호숫가, 캠프장 길가, 모닥불 주변에 가끔 쓰레기가 나와요. 다가가서 E로 주워요. 모닥불 옆 ♻️ 분리수거함에 버리면 하나당 솔방울 1개 (하루 최대 {cap}개). 다 모으면 '청소 대원 반다나' ♻️",
