    "上面的「🧭 去哪裡」可以直接到湖邊、迷霧森林、帳篷營地，或回自己的帳篷": "위의 '🧭 이동'으로 호수, 안개 숲, 텐트 캠핑장, 내 텐트로 바로 갈 수 있어요",
    "湖畔排行": "호숫가 순위",
    "可以看大家的歷史前 15 名，也能切到「自己」看你每種魚的最大紀錄": "모두의 역대 상위 15명을 보고, '나'에서 물고기별 최대 기록도 볼 수 있어요",
    "畫面更清爽": "더 깔끔해진 화면",
    "按鈕字變大、即時動態改成跑馬燈，看完就淡掉，不再擋住畫面": "버튼 글자가 커지고, 실시간 소식은 지나가며 사라져 화면을 가리지 않아요",
