    "🎣 今天前 30 條魚的松果拿滿了，之後每條 +1（稀有魚照算），明天再來！": "🎣 오늘 처음 30마리의 솔방울은 다 받았어요. 이제부터는 한 마리당 +1 (희귀 물고기는 그대로). 내일 또 와요!",
