    "🐾 買一次就能一直用，換別的動物也可以用（熊貓的黑白毛色固定，不能換毛色）": "🐾 한 번 사면 계속 쓸 수 있고 다른 동물에도 쓸 수 있어요 (판다는 흑백 털색 고정)",
