    "🐠 放哪一條魚進去？": "🐠 어떤 물고기를 넣을까요?",
    "還沒有釣過放得進這個魚缸的魚，去湖邊釣一條吧": "아직 이 어항에 들어갈 물고기를 못 잡았어요. 호수에서 낚아 봐요",
    "什麼魚都放得下，魚王也可以 🐉": "어떤 물고기든 들어가요. 물고기 왕도 🐉",
    "最多放 {n} 星的魚；大魚、魚王要用巨型水族箱": "{n}성까지의 물고기만 들어가요. 큰 물고기와 물고기 왕은 거대 수족관에",
