    "門口的紅色小郵筒，朋友來過就像收到信": "문 앞의 빨간 우체통, 친구가 오면 편지를 받은 것 같아요",
    "木頭野餐桌，桌上有格子布和野餐籃": "체크 천과 바구니가 놓인 나무 피크닉 테이블",
