    "亮晶晶的圓弧銀色拖車屋，門口掛著燈串": "입구에 전구 줄이 걸린 반짝이는 은색 트레일러",
    "雙層小木屋＋擴建到 20×20": "2층 통나무집 + 20×20까지 확장",
    "小舖新帳篷「雙層小木屋」，二樓也能擺家具；帳篷最大可以擴建到 20×20": "상점에 새로운 '2층 통나무집', 2층에도 가구를 놓을 수 있어요. 텐트는 최대 20×20까지 확장",
    "新家具：配色、隔間牆、魚缸、展示櫃": "새 가구: 색상, 칸막이 벽, 어항, 진열장",
    "買家具可以選顏色；用隔間牆分房間；魚缸放自己釣的魚（魚王要巨型水族箱）；沙發、床按 E 可以坐下、躺下": "가구 색을 고르고, 벽으로 방을 나누고, 어항에 직접 잡은 물고기를 넣어요 (물고기 왕은 거대 수족관). 소파와 침대에서 E를 누르면 앉거나 누워요",
    "動物外型": "동물 외형",
    "「👒 造型 → 🐾 外型」可以買特殊毛色（橘貓、三花⋯）、換尾巴和耳朵形狀": "'👒 코디 → 🐾 외형'에서 특별 털색(치즈냥, 삼색…)과 꼬리·귀 모양을 살 수 있어요",
    "門口擺設": "문 앞 장식",
    "小舖「🚙 門口擺設」：露營車、越野車、吊床⋯擺在帳篷營地的家門口": "상점 '🚙 문 앞 장식': 캠핑카, 오프로드 차, 해먹… 텐트 캠핑장 집 앞에 놓아요",
    "📖 上面多了「圖鑑」：釣到的魚、採到的東西都會收在這裡": "📖 위에 '도감'이 생겼어요: 잡은 물고기와 채집한 것이 여기 모여요",
    "👒 「造型」和「🔥 約朋友」打開了：朋友點你的連結進來玩 1 分鐘，就送你今天的造型": "👒 '코디'와 '🔥 친구 초대'가 열렸어요: 친구가 내 링크로 들어와 1분 놀면 오늘의 코디를 받아요",
    "💡 歡迎回來！多了「今日小靈感」，每天都有新的小任務": "💡 다시 왔군요! '오늘의 영감'이 생겼어요. 매일 새로운 작은 미션이 있어요",
    "🎉 營地全部打開了：到「🏪 營地小舖」買帳篷，也可以用「🧭 去哪裡」到迷霧森林採集": "🎉 캠프장이 모두 열렸어요: '🏪 캠프 상점'에서 텐트를 사거나 '🧭 이동'으로 안개 숲에 채집하러 가요",
    "🌙 明天見！": "🌙 내일 만나요!",
    "營地每天都有新東西，明天記得回來看看：": "캠프장엔 매일 새로운 게 있어요. 내일 또 와요:",
    "🌰 明天一進來就送 {n} 顆松果（連續來越多）": "🌰 내일 들어오자마자 솔방울 {n}개 (연속으로 올수록 더 많이)",
    "🌅 早上 9:30、晚上 9:30 營火時間：魚王、流星雨、松果加倍": "🌅 아침 9:30, 저녁 9:30 캠프파이어 타임: 물고기 왕, 유성우, 솔방울 2배",
    "👒 每天都有新的每日造型，朋友點你的連結進來玩 1 分鐘就拿到": "👒 매일 새로운 오늘의 코디, 친구가 내 링크로 들어와 1분 놀면 받아요",
    "🌙 晚上 7～11 點每半小時一場小活動": "🌙 저녁 7~11시 30분마다 미니 이벤트",
    "✅ 你已經有帳號了，換手機登入也找得回來": "✅ 계정이 있어서 폰을 바꿔도 로그인하면 되찾을 수 있어요",
    "⚠️ 還沒建帳號：松果、帳篷只存在這台裝置，清掉瀏覽器資料或換手機就找不回來": "⚠️ 아직 계정이 없어요: 솔방울과 텐트는 이 기기에만 저장돼요. 브라우저 데이터를 지우거나 폰을 바꾸면 못 찾아요",
    "👤 建立帳號存檔（30 秒）": "👤 계정 만들어 저장하기 (30초)",
    "💡 把這個網頁加到主畫面或書籤，下次一點就到": "💡 이 페이지를 홈 화면이나 북마크에 추가하면 다음엔 한 번에 와요",
    "🏕️ 你可以有自己的帳篷了！": "🏕️ 이제 내 텐트를 가질 수 있어요!",
