    "⛺ 買下來就是你的家：擺家具、換造型，關掉網頁再來都還在": "⛺ 사면 내 집이 돼요: 가구를 놓고 모양을 바꾸고, 다시 와도 그대로예요",
    "🏕️ 先到帳篷營地逛逛，看看大家把家布置成什麼樣子": "🏕️ 먼저 텐트 캠핑장을 둘러보며 다른 사람들의 집을 구경해요",
    "🏪 去營地小舖買帳篷": "🏪 캠프 상점에서 텐트 사기",
