    "贊助 NT${n} 以上，付款完成自動拿到，戴在頭上大家都看得到（每個月一款，過了這個月就換下一款）": "NT${n} 이상 후원하면 결제 후 자동으로 받아요. 모두가 볼 수 있어요 (매달 하나, 달이 바뀌면 다음 디자인)",
    "✅ 你已經有這個月的假髮了，謝謝你的支持 💛": "✅ 이번 달 가발을 이미 가지고 있어요. 응원 고마워요 💛",
    "⚠️ 測試模式：用綠界測試卡，不會真的扣款": "⚠️ 테스트 모드: ECPay 테스트 카드 사용, 실제 결제 없음",
    "贊助前要先建立帳號（👤 存檔），假髮才不會不見": "후원 전에 계정을 만들어 주세요 (👤 저장). 가발을 잃어버리지 않도록",
    "☕ 贊助功能即將推出，敬請期待！": "☕ 후원 기능 곧 출시!",
